    RibbonLargeButton { text: "Symbols"; icon: @image-url("icons/symbols.svg"); clicked => { root.tab-action("Symbols"); } }
}

    PrefCategory { text: "Virtual Printer"; icon: @image-url("icons/print.svg"); selected: root.active-cat == 5; clicked => { root.active-cat = 5; } }
    Rectangle { vertical-stretch: 1; }
